const raw = $json.output;
const parsed = typeof raw === 'string' ? JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')) : raw;
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Expected a recommendation object');
return [{ json: parsed }];
